//! Text art: the Anbani `TextArt` fonts and Rust renderer, gradients in ANSI and HTML, decorative homoglyphs and
//! the alphabet sheet the TUI sidebar reads.
//!
//! Fonts and homoglyphs are generated by `tools/gen.py` from `data/textart` and `data/vendor/homoglyph`.

mod alphabet;
pub mod colour;
#[rustfmt::skip]
mod fonts;
pub mod homoglyph;
#[rustfmt::skip]
mod homoglyphs;

use alloc::string::{String, ToString};
use alloc::vec::Vec;

use crate::Error;

pub use alphabet::{alphabet, Letter, ALPHABETS};
pub use fonts::FONTS;

/// The `TextArt` class a font belongs to; it decides the column separator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    /// `BlockFont`: cells separated by one space.
    Block,
    /// `LineFont`: cells joined with no separator (box-drawing strokes meet).
    Line,
    /// `SampleFont`: the text interleaved with `჻`, no glyphs.
    Sample,
}

/// One `TextArt` font.
#[derive(Debug)]
pub struct Font {
    /// Slug used on the command line (`block-regular`).
    pub key: &'static str,
    /// `TextArt`'s key and title (`Anbani Block Regular`).
    pub title: &'static str,
    /// Author named in the font file.
    pub author: &'static str,
    /// Rows per glyph (0 for Sample Style).
    pub height: usize,
    /// Its `TextArt` class.
    pub kind: Kind,
    /// Glyph rows per letter, sorted by letter (Mtavruli, Asomtavruli, Latin capitals, digits, punctuation).
    pub glyphs: &'static [(char, &'static [&'static str])],
}

impl Font {
    /// The rows of a letter's glyph, if the font draws it. Letters are matched as `TextArt` stores them (upper case).
    pub fn glyph(&self, c: char) -> Option<&'static [&'static str]> {
        self.glyphs.binary_search_by_key(&c, |(k, _)| *k).ok().map(|i| self.glyphs[i].1)
    }

    fn separator(&self) -> &'static str {
        match self.kind {
            Kind::Block => " ",
            Kind::Line | Kind::Sample => "",
        }
    }
}

/// A font by slug (case-insensitive) or by its `TextArt` title.
///
/// # Errors
/// `UnknownFont` when neither matches.
pub fn font(key: &str) -> Result<&'static Font, Error> {
    FONTS
        .iter()
        .find(|f| f.key.eq_ignore_ascii_case(key) || f.title == key)
        .ok_or_else(|| Error::UnknownFont(key.to_string()))
}

enum Cell {
    Glyph(&'static [&'static str]),
    Space,
    Blank,
}

/// Render `text` in `font` exactly as `TextArt`'s `generate()` does: upper-cased with full Unicode case mapping, one
/// cell per UTF-16 code unit, rows joined with the font's separator, each row ending in `\n`, and spaces turned into
/// U+2800 when the art holds braille dots. Deviations: a glyph row past the glyph's height is
/// empty (upstream prints `undefined`), empty text renders as an empty string, and Sample Style keeps non-BMP
/// characters whole.
pub fn render(font: &Font, text: &str) -> String {
    if font.kind == Kind::Sample {
        return sample(text);
    }
    let upper = text.to_uppercase();
    let mut cells = Vec::with_capacity(upper.len());
    for c in upper.chars() {
        if c == ' ' {
            cells.push(Cell::Space);
        } else if let Some(rows) = font.glyph(c) {
            cells.push(Cell::Glyph(rows));
        } else {
            cells.extend((0..c.len_utf16()).map(|_| Cell::Blank));
        }
    }
    let rows = match cells.first() {
        None => return String::new(),
        Some(Cell::Glyph(r)) => r.len(),
        Some(Cell::Space | Cell::Blank) => font.height + 1,
    };
    let separator = font.separator();
    let mut art = String::new();
    for j in 0..rows {
        for cell in &cells {
            art.push_str(match cell {
                Cell::Glyph(r) => r.get(j).copied().unwrap_or(""),
                Cell::Space if j < font.height => " ",
                Cell::Space | Cell::Blank => "",
            });
            art.push_str(separator);
        }
        art.push('\n');
    }
    if art.chars().any(|c| ('\u{2801}'..='\u{28FF}').contains(&c)) {
        art = art.replace(' ', "\u{2800}");
    }
    art
}

fn sample(text: &str) -> String {
    let mut out = String::from("჻");
    for (i, c) in text.chars().enumerate() {
        if i > 0 {
            out.push('჻');
        }
        out.push(c);
    }
    out.push('჻');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn upper_casing_maps_mkhedruli_to_mtavruli_and_nuskhuri_to_asomtavruli() {
        assert_eq!("აⴀ".to_uppercase(), "ᲐႠ");
    }

    #[test]
    fn every_font_is_found_by_slug_and_by_title() {
        for f in &FONTS {
            assert_eq!(font(f.key).map(|g| g.title), Ok(f.title));
            assert_eq!(font(f.title).map(|g| g.key), Ok(f.key));
        }
    }

    #[test]
    fn an_unknown_font_is_an_error() {
        assert_eq!(font("comic-sans").err(), Some(Error::UnknownFont("comic-sans".to_string())));
    }

    #[test]
    fn glyphs_are_sorted_for_binary_search() {
        for f in &FONTS {
            assert!(f.glyphs.windows(2).all(|w| w[0].0 < w[1].0), "{}", f.title);
        }
    }

    #[test]
    fn every_glyph_has_the_font_height_in_rows() {
        for f in FONTS.iter().filter(|f| f.kind != Kind::Sample) {
            assert!(f.glyphs.iter().all(|(_, rows)| rows.len() == f.height), "{}", f.title);
        }
    }

    #[test]
    fn empty_text_renders_as_empty_art() {
        assert_eq!(render(&FONTS[2], ""), "");
    }

    proptest::proptest! {
        #[test]
        fn art_has_one_line_per_row_and_one_cell_per_utf16_unit(text in "[აბგⴀႠaZ1 ?😀\u{300}]{1,12}") {
            for f in FONTS.iter().filter(|f| f.kind == Kind::Block) {
                let art = render(f, &text);
                let first_is_glyph = text.to_uppercase().chars().next().and_then(|c| f.glyph(c)).is_some();
                let rows = if first_is_glyph { f.height } else { f.height + 1 };
                proptest::prop_assert_eq!(art.matches('\n').count(), rows);
                let cells = text.to_uppercase().encode_utf16().count();
                let blank = if art.contains(' ') { ' ' } else { '\u{2800}' };
                let last = art.lines().last().unwrap_or("");
                if !first_is_glyph {
                    proptest::prop_assert_eq!(last.chars().filter(|c| *c == blank).count(), last.chars().count());
                }
                proptest::prop_assert!(art.lines().all(|l| l.chars().count() >= cells));
            }
        }
    }

    #[test]
    fn sample_style_wraps_every_character_in_separators() {
        let f = font("sample-style").expect("font");
        assert_eq!(render(f, "აბ"), "჻ა჻ბ჻");
        assert_eq!(render(f, ""), "჻჻");
    }
}
